+"use client";
+
+import { startTransition, useEffect, useState } from "react";
+
+import { Badge } from "@/components/ui/badge";
+import {
+  Card,
+  CardContent,
+  CardDescription,
+  CardHeader,
+  CardTitle,
+} from "@/components/ui/card";
+import {
+  type AgentMode,
+  type PublicDecision,
+  type PublicSnapshot,
+  type Route,
+  fetchPublicSnapshot,
+} from "@/lib/api";
+
+const ROUTES: Route[] = [
+  "CATALYST_CONTINUATION",
+  "LIQUIDITY_REVERSION",
+  "REGIME_TREND",
+  "NO_TRADE",
+];
+
+const routeLabels: Record<Route, string> = {
+  CATALYST_CONTINUATION: "Catalyst continuation",
+  LIQUIDITY_REVERSION: "Liquidity reversion",
+  REGIME_TREND: "Regime trend",
+  NO_TRADE: "No trade",
+};
+
+const modeClasses: Record<AgentMode, string> = {
+  RUNNING: "border-emerald-600/20 bg-emerald-600/10 text-emerald-800",
+  PAUSED: "border-amber-700/20 bg-amber-500/15 text-amber-900",
+  RISK_HALTED: "border-red-700/20 bg-red-600/10 text-red-800",
+  KILLED: "border-red-700/20 bg-red-600/10 text-red-800",
+};
+
+function formatTime(value: Date | string): string {
+  return new Intl.DateTimeFormat("en-US", {
+    month: "short",
+    day: "2-digit",
+    hour: "2-digit",
+    minute: "2-digit",
+    second: "2-digit",
+    timeZoneName: "short",
+  }).format(typeof value === "string" ? new Date(value) : value);
+}
+
+function routeBreakdown(decisions: PublicDecision[]) {
+  const routed = decisions.filter((decision) => decision.route !== null);
+  return ROUTES.map((route) => {
+    const count = routed.filter((decision) => decision.route === route).length;
+    return {
+      route,
+      count,
+      percentage: routed.length === 0 ? 0 : Math.round((count / routed.length) * 100),
+    };
+  });
+}
+
+function SectionTitle({ number, title, description }: { number: string; title: string; description: string }) {
+  return (
+    <div className="space-y-1">
+      <p className="font-mono text-[11px] font-semibold tracking-[0.16em] text-muted-foreground uppercase">{number}</p>
+      <h2 className="text-2xl font-semibold tracking-tight text-foreground sm:text-3xl">{title}</h2>
+      <p className="text-sm text-muted-foreground">{description}</p>
+    </div>
+  );
+}
+
+export function Dashboard() {
+  const [snapshot, setSnapshot] = useState<PublicSnapshot | null>(null);
+  const [error, setError] = useState<string | null>(null);
+
+  useEffect(() => {
+    const controller = new AbortController();
+
+    const refresh = async () => {
+      try {
+        const next = await fetchPublicSnapshot(controller.signal);
+        startTransition(() => {
+          setSnapshot(next);
+          setError(null);
+        });
+      } catch (reason) {
+        if (!controller.signal.aborted) {
+          setError(reason instanceof Error ? reason.message : "Public API unavailable");
+        }
+      }
+    };
+
+    void refresh();
+    const interval = window.setInterval(() => void refresh(), 30_000);
+    return () => {
+      controller.abort();
+      window.clearInterval(interval);
+    };
+  }, []);
+
+  const status = snapshot?.status;
+  const decisions = snapshot?.decisions ?? [];
+  const routes = routeBreakdown(decisions);
+  const exposureMessage =
+    status?.mode === "RUNNING" && status.reconciled
+      ? "New exposure may be evaluated by the Risk Governor."
+      : "New exposure is blocked.";
+
+  return (
+    <main className="min-h-screen bg-[radial-gradient(circle_at_50%_-20%,oklch(0.92_0.11_94),transparent_42%),var(--background)]">
+      <div className="mx-auto max-w-7xl px-4 py-6 sm:px-6 sm:py-10 lg:px-8">
+        <header className="mb-6 flex flex-col gap-6 border-b border-border pb-6 sm:mb-8 sm:flex-row sm:items-end sm:justify-between">
+          <div className="space-y-3">
+            <Badge variant="outline" className="border-primary/30 bg-primary/10 font-mono text-[10px] tracking-[0.14em] text-primary-foreground uppercase">Options alpha agents / public record</Badge>
+            <div>
+              <h1 className="text-4xl font-bold tracking-[-0.05em] text-foreground sm:text-6xl">Catalyst Router</h1>
+              <p className="mt-2 max-w-xl text-sm text-muted-foreground sm:text-base">Public flight recorder for a bounded, autonomous paper-trading agent.</p>
+            </div>
+          </div>
+          <div className="space-y-1 font-mono text-[11px] text-muted-foreground sm:text-right">
+            <div className="font-semibold tracking-[0.16em] text-destructive">READ-ONLY</div>
+            <p>Sanitized projection / 15 min delay</p>
+            <p>{snapshot ? `Received ${formatTime(snapshot.receivedAt)}` : "Connecting..."}</p>
+          </div>
+        </header>
+
+        {error ? <div role="alert" className="mb-6 rounded-lg border border-destructive/20 bg-destructive/10 px-4 py-3 text-sm text-destructive">{error}. Retrying every 30 seconds.</div> : null}
+
+        <Card className="mb-10 border-primary/20 bg-card/90">
+          <CardContent className="grid gap-5 pt-5 lg:grid-cols-[1.25fr_repeat(3,1fr)]">
+            <div className="space-y-3 rounded-xl bg-primary/10 p-5">
+              <p className="font-mono text-[11px] font-semibold tracking-[0.14em] text-muted-foreground uppercase">Agent authority</p>
+              <div className="flex flex-wrap items-center gap-3">
+                <span className="text-3xl font-bold tracking-tight sm:text-4xl">{status?.mode ?? "UNKNOWN"}</span>
+                {status ? <Badge variant="outline" className={modeClasses[status.mode]}>{status.mode.replaceAll("_", " ")}</Badge> : null}
+              </div>
+            </div>
+            {[
+              ["Reconciliation", status ? (status.reconciled ? "Matched" : "Pending") : "Unknown"],
+              ["Policy profile", "Base"],
+              ["Execution", exposureMessage],
+            ].map(([label, value]) => (
+              <div key={label} className="flex flex-col justify-center gap-2 border-l-0 border-border px-1 py-3 lg:border-l lg:px-5">
+                <p className="font-mono text-[11px] font-semibold tracking-[0.12em] text-muted-foreground uppercase">{label}</p>
+                <p className="text-sm font-medium leading-5">{value}</p>
+              </div>
+            ))}
+          </CardContent>
+        </Card>
+
+        <section className="mb-10" aria-labelledby="performance-title">
+          <SectionTitle number="01 / Performance field" title="Account ledger" description="Portfolio data will publish here once the sanitized ledger projection is available." />
+          <div className="mt-5 grid gap-5 lg:grid-cols-[1.65fr_1fr]">
